import path from 'path';
import { loadConfig } from '../core/config.js';
import { generateProject } from '../generator/index.js';
import { runGradleBuild, ensureGradleWrapper } from '../core/gradle.js';
import { log } from '../core/logger.js';
export async function buildCommand(args) {
    const isRelease = args.includes('--release') || args.includes('-r');
    const mode = isRelease ? 'release' : 'debug';
    log.banner();
    log.info(`Mode: ${mode.toUpperCase()}`);
    log.blank();
    const config = await loadConfig();
    const projectDirectory = await generateProject(config);
    ensureGradleWrapper(projectDirectory);
    const apkPath = await runGradleBuild(config, projectDirectory, mode);
    log.blank();
    log.success('==========================================');
    log.success('Build complete!');
    log.success(`APK -> ${apkPath}`);
    log.success('==========================================');
    log.blank();
    log.dim(`Install on device:  adb install -r "${path.basename(apkPath)}"`);
    if (mode === 'debug')
        log.dim('Signed release:     webapkify build --release');
    log.blank();
}
